arduino.globals:
#include "Adafruit_GFX.h"
#include "Adafruit_ILI9341.h"

#define TFT_DC_${COMP_SUFFIX} ${DC}
#define TFT_CS_${COMP_SUFFIX} ${CS}

Adafruit_ILI9341 tft_${COMP_SUFFIX} = Adafruit_ILI9341(TFT_CS_${COMP_SUFFIX}, TFT_DC_${COMP_SUFFIX});

arduino.setup:
tft_${COMP_SUFFIX}.begin();
tft_${COMP_SUFFIX}.setRotation(1);
tft_${COMP_SUFFIX}.fillScreen(ILI9341_BLACK);
tft_${COMP_SUFFIX}.setCursor(20, 100);
tft_${COMP_SUFFIX}.setTextColor(ILI9341_WHITE);
tft_${COMP_SUFFIX}.setTextSize(3);
tft_${COMP_SUFFIX}.println("OpenHW Studio");
tft_${COMP_SUFFIX}.setCursor(20, 140);
tft_${COMP_SUFFIX}.setTextSize(2);
tft_${COMP_SUFFIX}.println("TFT ILI9341 Ready");
delay(2000);

arduino.loop:
tft_${COMP_SUFFIX}.fillRect(100, 180, 50, 20, ILI9341_BLACK);
tft_${COMP_SUFFIX}.setCursor(20, 180);
tft_${COMP_SUFFIX}.setTextSize(2);
tft_${COMP_SUFFIX}.print("Time: ");
tft_${COMP_SUFFIX}.print(millis()/1000);
tft_${COMP_SUFFIX}.println("s");
delay(500);
